/* ───────────────────────── Muscle groups ───────────────────────── */

export type MuscleId =
    | 'chest'
    | 'shoulders'
    | 'biceps'
    | 'triceps'
    | 'forearms'
    | 'abs'
    | 'traps'
    | 'lats'
    | 'lowerBack'
    | 'glutes'
    | 'quads'
    | 'hamstrings'
    | 'calves';

export const MUSCLE_LABELS: Record<MuscleId, string> = {
    chest: 'Chest',
    shoulders: 'Shoulders',
    biceps: 'Biceps',
    triceps: 'Triceps',
    forearms: 'Forearms',
    abs: 'Abs',
    traps: 'Traps',
    lats: 'Back',
    lowerBack: 'Lower back',
    glutes: 'Glutes',
    quads: 'Quads',
    hamstrings: 'Hamstrings',
    calves: 'Calves',
};

/* ───────────────────────── Exercise → muscle rules ─────────────────────────
   Matched top to bottom against the lower-cased exercise name; the first match
   wins, so specific names (e.g. "leg curl") come before general ones ("curl"). */

interface Rule {
    re: RegExp;
    primary: MuscleId[];
    secondary?: MuscleId[];
}

const RULES: Rule[] = [
    // Triceps
    { re: /overhead.*extension|skull|french|push ?down|press ?down|tricep|close[- ]grip/, primary: ['triceps'], secondary: ['chest', 'shoulders'] },
    { re: /wrist/, primary: ['forearms'] },

    // Legs and glutes
    { re: /leg curl|hamstring curl|nordic/, primary: ['hamstrings'], secondary: ['calves'] },
    { re: /romanian|\brdl\b|stiff[- ]leg|good morning/, primary: ['hamstrings', 'glutes'], secondary: ['lowerBack'] },
    { re: /deadlift|rack pull/, primary: ['hamstrings', 'glutes', 'lowerBack'], secondary: ['lats', 'traps', 'forearms', 'quads'] },
    { re: /abduct|hip thrust|glute|kickback/, primary: ['glutes'], secondary: ['hamstrings'] },
    { re: /back extension|hyperextension|reverse hyper/, primary: ['lowerBack'], secondary: ['glutes', 'hamstrings'] },
    { re: /leg extension|sissy/, primary: ['quads'] },
    { re: /squat|leg press|hack|lunge|bulgarian|step[- ]?up|goblet/, primary: ['quads', 'glutes'], secondary: ['hamstrings', 'calves'] },
    { re: /calf|calves|donkey/, primary: ['calves'] },

    // Core
    { re: /oblique|russian|twist|side bend|woodchop|leg raise|knee raise|hanging|crunch|sit[- ]?up|plank|\bcore\b|\babs?\b|wheel|rollout/, primary: ['abs'] },
    { re: /farmer|carry|grip/, primary: ['forearms'], secondary: ['traps', 'abs'] },

    // Back, traps and rear delts
    { re: /face pull|rear delt|reverse fly|reverse flye|reverse pec|rear raise|bent[- ]over (lateral )?raise/, primary: ['shoulders'], secondary: ['traps', 'lats'] },
    { re: /pull[- ]?up|chin[- ]?up|pulldown|pull[- ]down|\blat\b/, primary: ['lats'], secondary: ['biceps', 'forearms', 'traps'] },
    { re: /shrug/, primary: ['traps'], secondary: ['forearms'] },
    { re: /upright row/, primary: ['shoulders', 'traps'], secondary: ['biceps'] },
    { re: /t[- ]?bar|pendlay|\brow\b|\brows\b/, primary: ['lats'], secondary: ['traps', 'biceps', 'lowerBack'] },

    // Biceps
    { re: /bicep|preacher|hammer|concentration|spider|curl/, primary: ['biceps'], secondary: ['forearms'] },

    // Shoulders
    { re: /overhead press|shoulder press|military|arnold|push press|\bohp\b|raise/, primary: ['shoulders'], secondary: ['triceps', 'traps'] },

    // Chest
    { re: /\bdips?\b/, primary: ['triceps', 'chest'], secondary: ['shoulders'] },
    { re: /incline|decline|bench|chest|push[- ]?up|\bfly\b|\bflye\b|\bflyes\b|pec|crossover/, primary: ['chest'], secondary: ['shoulders', 'triceps'] },
    { re: /press/, primary: ['chest'], secondary: ['triceps', 'shoulders'] },
];

export function musclesForExercise(name: string): Rule | null {
    if (!name) return null;
    const n = name.toLowerCase();
    return RULES.find((r) => r.re.test(n)) || null;
}

export interface MapExercise {
    name: string;
    isCompound?: boolean;
    /** Muscles from the exercise database (e.g. "quadriceps"). When present they are used instead of name matching. */
    primaryMuscles?: string[];
    secondaryMuscles?: string[];
    sets?: {
        setNumber?: number;
        weightKg?: number;
        reps?: number;
        completed?: boolean;
        isWarmup?: boolean;
    }[];
}

export interface MuscleContribution {
    exerciseName: string;
    sets: number;
    isPrimary: boolean;
}

/* Exercise-database muscle names → the groups drawn on the body */
const DB_MUSCLES: Record<string, MuscleId> = {
    abdominals: 'abs',
    abductors: 'glutes',
    adductors: 'quads',
    biceps: 'biceps',
    calves: 'calves',
    chest: 'chest',
    forearms: 'forearms',
    glutes: 'glutes',
    hamstrings: 'hamstrings',
    lats: 'lats',
    'lower back': 'lowerBack',
    'middle back': 'lats',
    neck: 'traps',
    quadriceps: 'quads',
    shoulders: 'shoulders',
    traps: 'traps',
    triceps: 'triceps',
};

function ruleFromDatabase(ex: MapExercise): Rule | null {
    const map = (list?: string[]) =>
        Array.from(
            new Set((list || []).map((m) => DB_MUSCLES[m.toLowerCase()]).filter(Boolean) as MuscleId[])
        );
    const primary = map(ex.primaryMuscles);
    if (primary.length === 0) return null;
    return { re: /^$/, primary, secondary: map(ex.secondaryMuscles).filter((m) => !primary.includes(m)) };
}

/* Main muscle = 1 per completed set, helper muscle = 0.5. Warm-up sets are ignored. */
export function getMuscleScores(exercises: MapExercise[]) {
    const scores: Partial<Record<MuscleId, number>> = {};
    const sources: Partial<Record<MuscleId, MuscleContribution[]>> = {};
    const unmapped: string[] = [];

    for (const ex of exercises || []) {
        if (!ex || !ex.name) continue;

        // Count completed non-warmup sets. If none are completed yet (e.g. active live workout), count planned sets (or at least 1) so added exercises reflect immediately.
        const completedSets = (ex.sets || []).filter(
            (s) =>
                !s.isWarmup &&
                (s.completed === true ||
                    (s.completed !== false && ((s.reps || 0) > 0 || (s.weightKg || 0) > 0)))
        ).length;

        const totalNonWarmup = (ex.sets || []).filter((s) => !s.isWarmup).length;
        const count = completedSets > 0 ? completedSets : Math.max(1, totalNonWarmup, ex.sets?.length || 1);
        if (count === 0) continue;

        const rule = ruleFromDatabase(ex) || musclesForExercise(ex.name);
        if (!rule) {
            if (!unmapped.includes(ex.name)) unmapped.push(ex.name);
            continue;
        }

        for (const m of rule.primary) {
            scores[m] = (scores[m] || 0) + count;
            (sources[m] ||= []).push({ exerciseName: ex.name, sets: count, isPrimary: true });
        }
        for (const m of rule.secondary || []) {
            scores[m] = (scores[m] || 0) + count * 0.5;
            (sources[m] ||= []).push({ exerciseName: ex.name, sets: count, isPrimary: false });
        }
    }

    return { scores, sources, unmapped };
}

