const FULL_AT = 8; // sets at which a muscle reaches full intensity / maximum red heat
const fmt = (n: number) => (Number.isInteger(n) ? String(n) : n.toFixed(1));
const FLIP = 'translate(260 0) scale(-1 1)';

/**
 * Calculates a dynamic heat color from soft light orange (low sets) -> vibrant flame orange -> deep reddish (high sets).
 */
export function getHeatColor(score: number): string {
    if (!score || score <= 0) return '#E4E4E7';
    // t ranges from 0 (1 set or less) to 1 (FULL_AT sets or more)
    const t = Math.min(1, Math.max(0, (score - 1) / (FULL_AT - 1)));

    // 0.0 -> Light Orange: rgb(255, 180, 110)
    // 0.5 -> Vibrant Flame Orange: rgb(255, 74, 0)
    // 1.0 -> Deep Reddish: rgb(205, 20, 20)
    let r: number, g: number, b: number;
    if (t < 0.5) {
        const localT = t / 0.5;
        r = 255;
        g = Math.round(180 + (74 - 180) * localT);
        b = Math.round(110 + (0 - 110) * localT);
    } else {
        const localT = (t - 0.5) / 0.5;
        r = Math.round(255 + (205 - 255) * localT);
        g = Math.round(74 + (20 - 74) * localT);
        b = Math.round(0 + (20 - 0) * localT);
    }
    return `rgb(${r}, ${g}, ${b})`;
}

function Figure({
    view,
    scores,
    active,
    onHover,
    onSelect,
}: {
    view: 'front' | 'back';
    scores: Partial<Record<MuscleId, number>>;
    active: MuscleId | null;
    onHover: (m: MuscleId | null) => void;
    onSelect: (m: MuscleId) => void;
}) {
    const uid = useId().replace(/[^a-zA-Z0-9]/g, '');
    const shapes = view === 'front' ? FRONT_SHAPES : BACK_SHAPES;
    const outline = view === 'front' ? FRONT_OUTLINE : BACK_OUTLINE;

    // Expand mirrored shapes into left + right copies
    const items = shapes.flatMap((s, i) =>
        s.mirror
            ? [
                { ...s, key: `${i}a`, flip: false },
                { ...s, key: `${i}b`, flip: true },
            ]
            : [{ ...s, key: `${i}`, flip: false }]
    );

    const renderShape = (s: (typeof items)[number]) => {
        const score = scores[s.m] || 0;
        const worked = score > 0;
        const selected = active === s.m;

        return (
            <path
                key={s.key}
                d={s.d}
                transform={s.flip ? FLIP : undefined}
                fill={worked ? getHeatColor(score) : selected ? '#D4D4D8' : '#E4E4E7'}
                stroke={selected ? '#111111' : worked ? 'rgba(0,0,0,0.06)' : 'none'}
                strokeWidth={selected ? 1.4 : 0.5}
                strokeLinejoin="round"
                className="cursor-pointer transition-[fill,stroke] duration-150"
                onMouseEnter={() => onHover(s.m)}
                onMouseLeave={() => onHover(null)}
                onClick={(e) => {
                    e.stopPropagation();
                    onSelect(s.m);
                }}
            >
                <title>{`${MUSCLE_LABELS[s.m]}${worked ? `: ${fmt(score)} sets` : ''}`}</title>
            </path>
        );
    };

    return (
        <figure className="flex-1 select-none text-center">
            <svg
                viewBox="0 0 260 744"
                role="img"
                aria-label={`${view === 'front' ? 'Front' : 'Back'} view of the body with worked muscles highlighted`}
                className="mx-auto h-auto w-full max-w-[170px]"
            >
                <defs>
                    <filter id={`${uid}-glow`} x="-20%" y="-20%" width="140%" height="140%">
                        <feDropShadow dx="0" dy="0" stdDeviation="2.5" floodColor="#FF4A00" floodOpacity="0.25" />
                    </filter>
                </defs>

                <path d={outline} fill="#FFFFFF" stroke="#D4D4D8" strokeWidth={2.2} strokeLinejoin="round" />

                {items.filter((s) => !(scores[s.m] || 0)).map(renderShape)}
                <g filter={`url(#${uid}-glow)`}>{items.filter((s) => (scores[s.m] || 0) > 0).map(renderShape)}</g>
            </svg>
            <figcaption className="mt-1 text-[11px] font-semibold text-zinc-500">
                {view === 'front' ? 'Front' : 'Back'}
            </figcaption>
        </figure>
    );
}

/* ───────────────────────── Component ───────────────────────── */

const DEFAULT_ROWS = 6;

export interface MuscleMapProps {
    exercises?: MapExercise[];
    title?: string;
    subtitle?: string;
    collapsible?: boolean;
    defaultOpen?: boolean;
    /** Stay open on xl screens even when collapsed on small ones (for a side panel). */
    alwaysOpenOnDesktop?: boolean;
    className?: string;
}

export default function MuscleMap({
    exercises = [],
    title = 'Muscles worked',
    subtitle,
    collapsible = true,
    defaultOpen = true,
    alwaysOpenOnDesktop = false,
    className = '',
}: MuscleMapProps) {
    const [open, setOpen] = useState(defaultOpen);
    const [showAll, setShowAll] = useState(false);
    const [active, setActive] = useState<MuscleId | null>(null);

    const { scores, sources, unmapped } = useMemo(() => getMuscleScores(exercises), [exercises]);

    const ranked = (Object.keys(scores) as MuscleId[])
        .filter((m) => (scores[m] || 0) > 0)
        .sort((a, b) => (scores[b] || 0) - (scores[a] || 0));

    const rows = showAll ? ranked : ranked.slice(0, DEFAULT_ROWS);
    const top = ranked[0] ? scores[ranked[0]] || 1 : 1;

    const summary = ranked.length
        ? ranked
            .slice(0, 3)
            .map((m) => MUSCLE_LABELS[m])
            .join(' · ')
        : 'Complete sets to see which muscles you worked';

    const toggle = (m: MuscleId) => setActive((p) => (p === m ? null : m));
    const contentClass = open ? 'block' : alwaysOpenOnDesktop ? 'hidden xl:block' : 'hidden';
    const locked = !collapsible;

    return (
        <section className={`rounded-2xl border border-zinc-200 bg-white ${className}`} aria-label="Muscles worked">
            <button
                type="button"
                onClick={() => !locked && setOpen((o) => !o)}
                aria-expanded={open}
                className={`flex w-full items-center justify-between gap-3 p-4 text-left sm:p-5 ${locked ? 'cursor-default' : ''
                    } ${alwaysOpenOnDesktop ? 'xl:pointer-events-none' : ''}`}
            >
                <div className="flex min-w-0 items-center gap-3">
                    <span className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-orange-50 text-[#FF4A00]">
                        <Flame className="h-5 w-5" />
                    </span>
                    <div className="min-w-0">
                        <h3 className="text-sm font-black uppercase tracking-tight">{title}</h3>
                        <p className="truncate text-xs text-zinc-500">{subtitle || summary}</p>
                    </div>
                </div>

                {!locked && (
                    <ChevronDown
                        className={`h-4 w-4 shrink-0 text-zinc-500 transition-transform ${open ? 'rotate-180' : ''} ${alwaysOpenOnDesktop ? 'xl:hidden' : ''
                            }`}
                    />
                )}
            </button>

            <div className={`${contentClass} px-4 pb-5 sm:px-5`}>
                <div className="flex gap-2 rounded-2xl bg-zinc-50 px-3 py-5 sm:gap-4 sm:px-5">
                    <Figure view="front" scores={scores} active={active} onHover={setActive} onSelect={toggle} />
                    <Figure view="back" scores={scores} active={active} onHover={setActive} onSelect={toggle} />
                </div>

                {/* Selected muscle */}
                {active && (
                    <div className="mt-3 rounded-xl border border-zinc-200 px-3.5 py-3">
                        <div className="flex items-center justify-between">
                            <span className="text-sm font-black uppercase tracking-tight">{MUSCLE_LABELS[active]}</span>
                            <span className="font-mono text-xs font-black text-[#FF4A00]">
                                {scores[active] ? `${fmt(scores[active] || 0)} sets` : 'Not worked'}
                            </span>
                        </div>
                        {sources[active] && sources[active]!.length > 0 && (
                            <p className="mt-1 text-xs text-zinc-500">
                                {sources[active]!.map((c) => `${c.exerciseName}${c.isPrimary ? '' : ' (helper)'}`).join(', ')}
                            </p>
                        )}
                    </div>
                )}

                {/* Ranking */}
                {ranked.length > 0 && (
                    <div className="mt-4">
                        <ul className="space-y-2.5">
                            {rows.map((m) => {
                                const v = scores[m] || 0;
                                return (
                                    <li key={m}>
                                        <button
                                            type="button"
                                            onClick={() => toggle(m)}
                                            className="flex w-full items-center gap-3 text-left text-xs"
                                        >
                                            <span className="w-20 shrink-0 truncate font-semibold text-zinc-800">{MUSCLE_LABELS[m]}</span>
                                            <span className="h-1.5 flex-1 overflow-hidden rounded-full bg-zinc-100">
                                                <span
                                                    className="block h-full rounded-full transition-all duration-300"
                                                    style={{ width: `${Math.max(8, (v / top) * 100)}%`, backgroundColor: getHeatColor(v) }}
                                                />
                                            </span>
                                            <span className="w-14 shrink-0 text-right font-mono font-bold text-zinc-900">
                                                {fmt(v)} {v === 1 ? 'set' : 'sets'}
                                            </span>
                                        </button>
                                    </li>
                                );
                            })}
                        </ul>

                        {ranked.length > DEFAULT_ROWS && (
                            <button
                                type="button"
                                onClick={() => setShowAll((s) => !s)}
                                className="mt-3 text-xs font-bold text-[#FF4A00] hover:underline"
                            >
                                {showAll ? 'Show less' : `Show all ${ranked.length}`}
                            </button>
                        )}
                    </div>
                )}

                <p className="mt-4 text-[11px] leading-relaxed text-zinc-400">
                    Main muscles count a full set, helper muscles half. Warm-ups aren&apos;t counted.
                </p>

                {unmapped.length > 0 && (
                    <p className="mt-1 text-[11px] leading-relaxed text-zinc-400">
                        Not tracked yet: {Array.from(new Set(unmapped)).join(', ')}
                    </p>
                )}
            </div>
        </section>
    );
}